{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four category models, reduce dropout to preserve context in short histories and lower the learning rate to stabilize updates with less regularization. Preserve model dimensions, loss, optimizer and training limits. The predictor already loads the trained architecture and disables dropout during inference.",
      "edits": [
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.2\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.1\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"1e-3\"))",
          "replace": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"8e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly reduce BERT4Rec dropout from 0.2 to 0.1 and learning rate from 1e-3 to 8e-4 across all four datasets, retaining one independent checkpoint per category."
}
